{
  "prose": [
    {
      "key": "headline",
      "text": "Trade character consistency for unit cost: {arm:f64} cuts reply cost by {cost.uplift.f64|abs} while dropping character retention {contrast.f64.persona.delta|abs|pts} points."
    },
    {
      "key": "lede",
      "text": "{arm:f64} saves {cost.uplift.f64|abs} per thousand replies while meeting all safety guardrails, but drops character consistency from {judged.persona.prod|pct} to {judged.persona.f64|pct}. A leadership ruling on persona degradation tolerance decides whether to switch from {arm:prod}."
    },
    {
      "key": "flag.title",
      "text": "No trade-off rule set in advance"
    },
    {
      "key": "flag.text",
      "text": "Product leadership must set the maximum acceptable drop in character retention per dollar saved; guardrail measurements remain binding."
    },
    {
      "key": "decision.the_trade",
      "text": "{arm:f64} lowers cost from {cost_per_1k.prod|usd} to {cost_per_1k.f64|usd} per thousand replies, paying {contrast.f64.persona.delta|abs|pts} points of persona retention ({contrast.f64.persona.interval|pts})."
    },
    {
      "key": "decision.where_it_flips",
      "text": "If preserving character consistency is worth more than ten cents per percentage point, stay on {arm:prod}; below that threshold, {arm:f64} is favored."
    },
    {
      "key": "decision.our_lean",
      "text": "Adopt {arm:f64} if monthly cost savings justify minor personality drift in long sessions; reject {arm:cor} for breaching {criteria.specul.threshold|pct} on speculation."
    },
    {
      "key": "decision.what_settles_it",
      "text": "A leadership ruling on persona loss tolerance, or a user study testing whether listeners notice drift in dialogues beyond turn five."
    },
    {
      "key": "summary.0.title",
      "text": "Change in persona consistency vs Production"
    },
    {
      "key": "summary.1.title",
      "text": "Cost per thousand replies"
    },
    {
      "key": "sections.persona_contrasts.eyebrow",
      "text": "Guardrails and persona change"
    },
    {
      "key": "sections.persona_contrasts.headline",
      "text": "{arm:f64} preserves music accuracy while declining {contrast.f64.persona.delta|abs|pts} points on character retention"
    },
    {
      "key": "sections.persona_contrasts.takeaway",
      "text": "All candidates regress on persona; only {arm:f64} preserves the {criteria.facts.threshold|pct} music accuracy and {criteria.specul.threshold|pct} anti-speculation guardrails."
    },
    {
      "key": "sections.persona_contrasts.title",
      "text": ""
    },
    {
      "key": "sections.persona_contrasts.caption",
      "text": "Family intervals at 95% confidence without multiplicity adjustment."
    },
    {
      "key": "sections.depth_breakdown.eyebrow",
      "text": "Loss concentration by conversation depth"
    },
    {
      "key": "sections.depth_breakdown.headline",
      "text": "Persona degradation concentrates in extended dialogues beyond turn five"
    },
    {
      "key": "sections.depth_breakdown.takeaway",
      "text": "{arm:f64} tracks {arm:prod} closely through turn five, but degrades sharply in turns eleven and above."
    },
    {
      "key": "sections.depth_breakdown.title",
      "text": ""
    },
    {
      "key": "sections.depth_breakdown.caption",
      "text": "Strata intervals are descriptive and uncorrected across depths."
    },
    {
      "key": "sections.scenario_breakdown.eyebrow",
      "text": "Scenario sensitivity"
    },
    {
      "key": "sections.scenario_breakdown.headline",
      "text": "Corrections and banter trigger the steepest character drops across candidates"
    },
    {
      "key": "sections.scenario_breakdown.takeaway",
      "text": "Task-oriented turns retain persona well, whereas defensive turns account for the majority of persona regressions."
    },
    {
      "key": "sections.scenario_breakdown.title",
      "text": ""
    },
    {
      "key": "sections.scenario_breakdown.caption",
      "text": "Scenario shifts are uncorrected differences from the control mean."
    },
    {
      "key": "durable_claims.0",
      "text": "{arm:f64} regresses persona retention by {contrast.f64.persona.delta|pts} points ({contrast.f64.persona.interval|pts}) while reducing cost from {measure.cost_per_1k.prod.mean|usd} to {measure.cost_per_1k.f64.mean|usd} per thousand replies."
    },
    {
      "key": "durable_claims.1",
      "text": "{arm:cor} fails the speculation guardrail at {measure.specul.cor.mean|pct} against the required {criteria.specul.threshold|pct} threshold ({contrast.cor.specul.delta|pts} points vs {arm:prod})."
    },
    {
      "key": "method.0.term",
      "text": "Sample size"
    },
    {
      "key": "method.0.text",
      "text": "Ran {scoreboard.prod.ran|int} trials across {scoreboard.prod.cases|int} cases per arm."
    },
    {
      "key": "method.1.term",
      "text": "Persona evaluation"
    },
    {
      "key": "method.1.text",
      "text": "Calibrated judge against {judged.persona.calibration_ratings|int} human ratings with agreement of {judged.persona.agreement}."
    },
    {
      "key": "method.2.term",
      "text": "Guardrail checks"
    },
    {
      "key": "method.2.text",
      "text": "Catalog truth matching for music facts and automated checks for prompt speculation refusal."
    },
    {
      "key": "method.3.term",
      "text": "Interval method"
    },
    {
      "key": "method.3.text",
      "text": "Paired difference intervals at 95% confidence without multiplicity adjustment."
    },
    {
      "key": "method.4.term",
      "text": "Cost model"
    },
    {
      "key": "method.4.text",
      "text": "Measured token usage multiplied by model list prices per thousand turns."
    },
    {
      "key": "method.5.term",
      "text": "Excluded measures"
    },
    {
      "key": "method.5.text",
      "text": "Tool calling execution was evaluated descriptively without comparative hypothesis testing."
    },
    {
      "key": "explore.title",
      "text": "Trade-off valuation"
    },
    {
      "key": "explore.recomputes",
      "text": "Adjusting the dollar valuation per point of persona retention toggles recommendation between {arm:prod} and {arm:f64}."
    },
    {
      "key": "explore.controls.price_trade.title",
      "text": "Dollar value per point of persona"
    }
  ]
}

